<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'

const props = defineProps<{
  count: number
  selected: number
  suffix: string
}>()

const emit = defineEmits<{ 'update:selected': [value: number] }>()
const ITEM_HEIGHT = 44
const scroller = ref<HTMLElement>()
const values = computed(() => Array.from({ length: props.count }, (_, index) => index))
let scrollTimer: ReturnType<typeof setTimeout> | undefined

function scrollToValue(value: number, smooth = false): void {
  if (!scroller.value) return
  scroller.value.scrollTo({
    top: value * ITEM_HEIGHT,
    behavior: smooth ? 'smooth' : 'auto',
  })
}

function choose(value: number): void {
  emit('update:selected', value)
  void nextTick(() => scrollToValue(value, true))
}

function onScroll(): void {
  if (scrollTimer) clearTimeout(scrollTimer)
  scrollTimer = setTimeout(() => {
    if (!scroller.value) return
    const value = Math.max(0, Math.min(props.count - 1, Math.round(scroller.value.scrollTop / ITEM_HEIGHT)))
    if (value !== props.selected) emit('update:selected', value)
  }, 90)
}

function onKeydown(event: KeyboardEvent): void {
  if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
  event.preventDefault()
  const delta = event.key === 'ArrowDown' ? 1 : -1
  choose(Math.max(0, Math.min(props.count - 1, props.selected + delta)))
}

watch(() => props.selected, (value) => void nextTick(() => scrollToValue(value)))
onMounted(() => scrollToValue(props.selected))
onBeforeUnmount(() => { if (scrollTimer) clearTimeout(scrollTimer) })
</script>

<template>
  <div class="wheel-frame">
    <div class="selection-band" aria-hidden="true" />
    <div
      ref="scroller"
      class="wheel"
      role="listbox"
      :aria-label="suffix === '时' ? '小时选择' : '分钟选择'"
      tabindex="0"
      @scroll.passive="onScroll"
      @keydown="onKeydown"
    >
      <button
        v-for="value in values"
        :key="value"
        type="button"
        role="option"
        :aria-selected="value === selected"
        :class="{ selected: value === selected }"
        tabindex="-1"
        @click="choose(value)"
      >
        {{ value }}{{ suffix }}
      </button>
    </div>
  </div>
</template>

<style scoped>
.wheel-frame { position: relative; height: 132px; overflow: hidden; }
.wheel-frame::before, .wheel-frame::after { content: ''; position: absolute; z-index: 2; right: 0; left: 0; height: 34px; pointer-events: none; }
.wheel-frame::before { top: 0; background: linear-gradient(var(--color-surface), transparent); }
.wheel-frame::after { bottom: 0; background: linear-gradient(transparent, var(--color-surface)); }
.selection-band { position: absolute; z-index: 0; top: 44px; right: 4px; left: 4px; height: 44px; border-radius: 11px; background: var(--color-surface-muted); pointer-events: none; }
.wheel { position: relative; z-index: 1; height: 132px; overflow-x: hidden; overflow-y: auto; padding: 44px 0; outline: none; scroll-snap-type: y mandatory; scrollbar-width: none; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; }
.wheel::-webkit-scrollbar { display: none; }
.wheel button { display: flex; width: 100%; height: 44px; align-items: center; justify-content: center; padding: 0; border: 0; background: transparent; color: var(--color-text-secondary); font-variant-numeric: tabular-nums; scroll-snap-align: center; }
.wheel button.selected { color: var(--color-text); font-weight: 700; }
.wheel:focus-visible { border-radius: 12px; outline: 3px solid rgb(22 119 255 / 35%); outline-offset: -3px; }
@media (prefers-reduced-motion: reduce) { .wheel { scroll-behavior: auto; } }
</style>
