<script setup lang="ts">
import { computed, ref } from 'vue'
import { Delete } from '@lucide/vue'

/** 键盘顶部分类快选行的最小数据 */
export interface QuickCategory {
  id: string
  name: string
}

/**
 * 金额自定义键盘（替代系统 inputmode="decimal" 的系统键盘，计算器语义）。
 *
 * 数据流：父组件用 v-model 双向绑定 amountText（字符串，承载「表达式」，如 "5+1+3-2"）。
 *   - 数字 / 小数点：在当前段（最后一个运算符之后）追加
 *   - + / -：追加运算符；末位已是运算符则替换（"5++" → "5+"）；空表达式前补 0
 *   - ⌫：删除表达式末位
 *   - 实时结果由父组件用 evaluateAmountExpression(amountText) 计算（金额实时跟着算）
 *   - 保存 / 再记：emit 事件，由父组件决定动作
 *
 * 段内限制：整数位最多 8 位、小数位最多 2 位；非法结果由保存前的领域校验把关。
 */

const props = withDefaults(defineProps<{
  /** v-model 绑定：金额表达式，如 "5+1+3-2" 或 "12.34"；空字符串表示未输入 */
  modelValue: string
  /** 支出/收入样式：仅影响金额显示色（键盘本身不变色） */
  type?: 'expense' | 'income'
  /** 编辑模式下隐藏"再记一笔"按钮（只显示"保存"） */
  hideAddAnother?: boolean
  /** 编辑模式：首次按数字/运算符时先清空预填的旧金额（⌫ 仍为逐位删除） */
  autoClear?: boolean
  /** 最近常用分类（键盘上方快选行）；当前选中的分类 id */
  recentCategories?: QuickCategory[]
  selectedCategoryId?: string
}>(), {
  type: 'expense',
  hideAddAnother: false,
  autoClear: false,
  recentCategories: () => [],
  selectedCategoryId: '',
})

const emit = defineEmits<{
  'update:modelValue': [value: string]
  save: []
  'add-another': []
  'select-category': [id: string]
}>()

/** 编辑模式左下角占位：一键清空金额表达式 */
function onClear(): void {
  emit('update:modelValue', '')
}

/** 取表达式的当前段：最后一个 + / - 之后的数字段（输入约束按段生效） */
function segmentOf(value: string): string {
  const plus = Math.max(value.lastIndexOf('+'), value.lastIndexOf('-'))
  return plus === -1 ? value : value.slice(plus + 1)
}

function emitNext(next: string): void {
  emit('update:modelValue', next)
}

/** 编辑模式首次输入（数字/小数点/运算符）前的基准值：消费掉一次性清空标记后返回空串 */
const autoCleared = ref(false)
function inputBase(): string {
  if (props.autoClear && !autoCleared.value) {
    autoCleared.value = true
    emitNext('')
    return ''
  }
  return props.modelValue
}

function appendDigit(digit: string): void {
  const value = inputBase()
  const segment = segmentOf(value)
  const dot = segment.indexOf('.')
  const integer = dot === -1 ? segment : segment.slice(0, dot)
  const fraction = dot === -1 ? '' : segment.slice(dot + 1)
  if (dot !== -1 && fraction.length >= 2) return // 小数位最多 2 位
  if (integer.replace(/^0+(?=\d)/, '').length >= 8) return // 整数位最多 8 位
  let nextSegment: string
  if (integer === '0') nextSegment = digit // 前导 0 抑制："0"+"2" → "2"
  else if (integer === '' && dot !== -1) nextSegment = `0.${fraction}${digit}` // ".5" 补整位
  else if (dot === -1) nextSegment = `${integer}${digit}`
  else nextSegment = `${integer}.${fraction}${digit}`
  const prefix = value.slice(0, value.length - segment.length)
  emitNext(`${prefix}${nextSegment}`)
}

function appendDot(): void {
  const value = inputBase()
  const segment = segmentOf(value)
  if (segment.includes('.')) return
  const prefix = value.slice(0, value.length - segment.length)
  emitNext(`${prefix}${segment === '' ? '0.' : `${segment}.`}`)
}

/** 追加运算符（计算器语义）：末位已是运算符则替换；表达式为空则前补 0 */
function appendOperator(op: '+' | '-'): void {
  const value = inputBase()
  if (value === '') { emitNext(`0${op}`); return }
  const last = value.slice(-1)
  if (last === '+' || last === '-') { emitNext(`${value.slice(0, -1)}${op}`); return }
  emitNext(`${value}${op}`)
}

function backspace(): void {
  const v = props.modelValue
  if (!v) return
  emitNext(v.slice(0, -1))
}

function onSave(): void { emit('save') }
function onAddAnother(): void { emit('add-another') }

function onKey(key: string): void {
  switch (key) {
    case '.': return appendDot()
    case 'back': return backspace()
    case '+': return appendOperator('+')
    case '-': return appendOperator('-')
    default: return appendDigit(key)
  }
}
</script>

<template>
  <div class="number-pad" role="group" aria-label="金额键盘">
    <!-- 最近常用分类快选：点一下直接切分类，免开选择器 -->
    <div v-if="recentCategories.length" class="quick-categories" role="listbox" aria-label="最近常用分类">
      <button
        v-for="category in recentCategories"
        :key="category.id"
        type="button"
        class="quick-chip"
        :class="{ active: category.id === selectedCategoryId }"
        @click="emit('select-category', category.id)"
      >{{ category.name }}</button>
    </div>
    <div class="key-row">
      <button type="button" class="key" @click="onKey('1')">1</button>
      <button type="button" class="key" @click="onKey('2')">2</button>
      <button type="button" class="key" @click="onKey('3')">3</button>
      <button type="button" class="key key-func key-side-action key-delete" aria-label="删除" @click="onKey('back')">
        <Delete :size="22" />
      </button>
    </div>
    <div class="key-row">
      <button type="button" class="key" @click="onKey('4')">4</button>
      <button type="button" class="key" @click="onKey('5')">5</button>
      <button type="button" class="key" @click="onKey('6')">6</button>
      <button type="button" class="key key-func key-side-action key-minus" @click="onKey('-')" aria-label="减">−</button>
    </div>
    <div class="key-row">
      <button type="button" class="key" @click="onKey('7')">7</button>
      <button type="button" class="key" @click="onKey('8')">8</button>
      <button type="button" class="key" @click="onKey('9')">9</button>
      <button type="button" class="key key-func key-side-action key-plus" @click="onKey('+')" aria-label="加">+</button>
    </div>
    <div class="key-row">
      <button
        v-if="!hideAddAnother"
        type="button"
        class="key key-side"
        @click="onAddAnother"
      ><span class="two-line-label">再记<br>一笔</span></button>
      <button v-else type="button" class="key key-side" aria-label="清空金额" @click="onClear">清空</button>
      <button type="button" class="key" @click="onKey('0')">0</button>
      <button type="button" class="key" @click="onKey('.')">.</button>
      <button type="button" class="key key-save" @click="onSave"><span class="save-label">保存</span></button>
    </div>
  </div>
</template>

