export const WEEKDAY_LABELS = ['一', '二', '三', '四', '五', '六', '日'] as const

export interface CalendarDay {
  key: string
  date: Date
  day: number
  selected: boolean
  today: boolean
}

function sameDay(left: Date, right: Date): boolean {
  return left.getFullYear() === right.getFullYear()
    && left.getMonth() === right.getMonth()
    && left.getDate() === right.getDate()
}

export function createMonthCells(
  year: number,
  month: number,
  selected: Date,
  today: Date,
): Array<CalendarDay | null> {
  const first = new Date(year, month - 1, 1)
  const leading = (first.getDay() + 6) % 7
  const dayCount = new Date(year, month, 0).getDate()

  return Array.from({ length: 42 }, (_, index) => {
    const day = index - leading + 1
    if (day < 1 || day > dayCount) return null
    const date = new Date(year, month - 1, day)
    return {
      key: `${year}-${month}-${day}`,
      date,
      day,
      selected: sameDay(date, selected),
      today: sameDay(date, today),
    }
  })
}

export function combineLocalDateTime(date: Date, hour: number, minute: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate(), hour, minute)
}

export function formatRecordDateTime(date: Date, customized: boolean, now = new Date()): string {
  const datePart = `${date.getMonth() + 1}月${date.getDate()}日`
  if (!customized && sameDay(date, now)) return `${datePart}（今天）`

  const timePart = `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`
  return date.getFullYear() === now.getFullYear()
    ? `${datePart} ${timePart}`
    : `${date.getFullYear()}年${datePart} ${timePart}`
}
