<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, toRef, watch } from 'vue'
import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp } from '@lucide/vue'
import NumberWheel from './NumberWheel.vue'
import { combineLocalDateTime, createMonthCells, WEEKDAY_LABELS, type CalendarDay } from './date-time'
import { useOverlayBackClose } from '@/ui/overlay-back-stack'

const props = defineProps<{
  open: boolean
  initial: Date
}>()

const emit = defineEmits<{
  close: []
  confirm: [value: Date]
}>()

const dialog = ref<HTMLDialogElement>()
// 安卓返回手势优先关闭日期选择器（而不是后退页面）
useOverlayBackClose(toRef(props, 'open'), () => emit('close'))
const selected = ref(new Date())
const viewYear = ref(0)
const viewMonth = ref(0)
const today = ref(new Date())
const withTime = ref(true)
const hour = ref(0)
const minute = ref(0)
let returnFocus: HTMLElement | null = null

const monthTitle = computed(() => `${viewYear.value}年${viewMonth.value}月`)
const cells = computed(() => createMonthCells(viewYear.value, viewMonth.value, selected.value, today.value))

function resetDraft(): void {
  const initial = props.initial
  selected.value = new Date(initial.getFullYear(), initial.getMonth(), initial.getDate())
  viewYear.value = initial.getFullYear()
  viewMonth.value = initial.getMonth() + 1
  hour.value = initial.getHours()
  minute.value = initial.getMinutes()
  // 时刻默认收起（按需点开编辑）；确认时保留 initial 的时分，不因收起而丢失已有时刻
  withTime.value = false
  const now = new Date()
  today.value = new Date(now.getFullYear(), now.getMonth(), now.getDate())
}

async function openDialog(): Promise<void> {
  resetDraft()
  returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null
  await nextTick()
  if (!dialog.value || dialog.value.open) return
  if (typeof dialog.value.showModal === 'function') dialog.value.showModal()
  else dialog.value.setAttribute('open', '')
}

async function closeDialog(): Promise<void> {
  if (dialog.value?.open) {
    if (typeof dialog.value.close === 'function') dialog.value.close()
    else dialog.value.removeAttribute('open')
  }
  await nextTick()
  returnFocus?.focus()
  returnFocus = null
}

function requestClose(): void {
  emit('close')
}

function shiftMonth(delta: number): void {
  const target = new Date(viewYear.value, viewMonth.value - 1 + delta, 1)
  viewYear.value = target.getFullYear()
  viewMonth.value = target.getMonth() + 1
}

function chooseDate(cell: CalendarDay): void {
  selected.value = cell.date
}

function confirmSelection(): void {
  emit('confirm', combineLocalDateTime(
    selected.value,
    withTime.value ? hour.value : props.initial.getHours(),
    withTime.value ? minute.value : props.initial.getMinutes(),
  ))
}

function dateLabel(cell: CalendarDay): string {
  return `${cell.date.getFullYear()}年${cell.date.getMonth() + 1}月${cell.day}日${cell.today ? '，今天' : ''}`
}

watch(() => props.open, (open) => { if (open) void openDialog(); else void closeDialog() })
onMounted(() => { if (props.open) void openDialog() })
onBeforeUnmount(() => { returnFocus = null })
</script>

<template>
  <dialog
    ref="dialog"
    class="date-time-dialog"
    aria-labelledby="date-time-title"
    @cancel.prevent="requestClose"
    @click.self="requestClose"
  >
    <section class="date-time-panel">
      <div class="drag-handle" aria-hidden="true" />
      <header class="sheet-header">
        <h2 id="date-time-title">选择日期</h2>
        <button type="button" class="done-button" @click="confirmSelection">完成</button>
      </header>

      <div class="month-nav">
        <button type="button" aria-label="上个月" @click="shiftMonth(-1)"><ChevronLeft :size="24" /></button>
        <strong aria-live="polite">{{ monthTitle }}</strong>
        <button type="button" aria-label="下个月" @click="shiftMonth(1)"><ChevronRight :size="24" /></button>
      </div>

      <div class="weekdays" aria-hidden="true">
        <span v-for="label in WEEKDAY_LABELS" :key="label">{{ label }}</span>
      </div>
      <div class="calendar-grid" role="grid" :aria-label="monthTitle">
        <template v-for="(cell, index) in cells" :key="cell?.key ?? `blank-${index}`">
          <button
            v-if="cell"
            type="button"
            role="gridcell"
            :aria-label="dateLabel(cell)"
            :aria-selected="cell.selected"
            :aria-current="cell.today ? 'date' : undefined"
            :class="{ selected: cell.selected, today: cell.today }"
            @click="chooseDate(cell)"
          >
            {{ cell.today ? '今' : cell.day }}
          </button>
          <span v-else aria-hidden="true" />
        </template>
      </div>

      <div class="divider" />
      <!-- 整行都是点击区域（切换时刻展开/收起） -->
      <button type="button" class="time-toggle-row" :aria-expanded="withTime" @click="withTime = !withTime">
        <span id="time-toggle-label">时刻</span>
        <component :is="withTime ? ChevronUp : ChevronDown" :size="22" class="expand-icon" aria-hidden="true" />
      </button>

      <div v-if="withTime" class="time-wheels">
        <NumberWheel v-model:selected="hour" :count="24" suffix="时" />
        <NumberWheel v-model:selected="minute" :count="60" suffix="分" />
      </div>
      <div v-else class="time-off-space" aria-hidden="true" />
    </section>
  </dialog>
</template>

