.month-nav { display: flex; min-height: 48px; align-items: center; justify-content: center; gap: 8px; }
.month-nav button { display: grid; width: 48px; height: 48px; place-items: center; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.month-nav strong { min-width: 112px; text-align: center; font-size: 17px; }
.weekdays, .calendar-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); padding-right: 6px; padding-left: 6px; }
.weekdays span { display: grid; height: 28px; place-items: center; color: var(--color-text-secondary); font-size: 12px; }
/* 日历行高按当月实际周数生成（固定 6 行会在 5 周月份留出大片空白） */
.calendar-grid { grid-auto-rows: 44px; }
.calendar-grid button { display: grid; width: 44px; max-width: 100%; height: 44px; place-self: center; place-items: center; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--color-text); font-size: 16px; }
.calendar-grid button.today { color: var(--color-primary); font-weight: 700; }
.calendar-grid button.selected { background: var(--color-primary); color: white; font-weight: 700; }
.divider { height: 1px; margin-top: 0; background: var(--color-border); }
/* 时刻行：整行按钮化（点击区域铺满一行），紧贴日历底部分割线 */
.time-toggle-row { display: flex; width: 100%; min-height: 54px; align-items: center; justify-content: space-between; padding: 0 16px; border: 0; background: transparent; color: var(--color-text); font-size: 17px; font-weight: 600; cursor: pointer; }
.expand-icon { color: var(--color-text-secondary); }
.time-wheels { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 0 16px 12px; }
.time-off-space { height: 8px; }
@media (min-width: 640px) {
  .date-time-dialog { inset: 0; width: min(560px, calc(100% - 32px)); height: fit-content; margin: auto; }
  .date-time-panel { position: static; border-radius: var(--radius-lg); }
}
@media (prefers-reduced-motion: reduce) { .switch, .switch span { transition: none; } }
</style>
