<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { ChevronLeft, ChevronDown, Lock, Trash2 } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { Category, LedgerType } from '@/domain/models/category'
import { evaluateAmountExpression, formatCents } from '@/domain/services/money'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'
import ConfirmGraphic from '@/components/ConfirmGraphic.vue'
import CategoryIcon from '@/components/CategoryIcon.vue'
import CategoryPicker from '@/features/categories/CategoryPicker.vue'
import DateTimePickerSheet from '@/features/transactions/DateTimePickerSheet.vue'
import NumberPad from '@/components/NumberPad.vue'
import { formatRecordDateTime } from '@/features/transactions/date-time'

const route = useRoute()
const router = useRouter()
const store = useAppStore()
const editingId = computed(() => typeof route.params.id === 'string' ? route.params.id : undefined)
const copyFromId = computed(() => typeof route.query.copyFrom === 'string' ? route.query.copyFrom : undefined)
const type = ref<LedgerType>('expense')
const amountText = ref('')
const categoryId = ref('')
const bookedAt = ref(new Date())
const dateCustomized = ref(false)
const note = ref('')
const pickerOpen = ref(false)
const datePickerOpen = ref(false)
const activationOpen = ref(false)
const deleteOpen = ref(false)
const saving = ref(false)
const deleting = ref(false)
const recentIds = ref<string[]>([])
/**
 * 数字键盘显隐状态机（备注与金额共用屏幕底部，避免双键盘叠屏与切换闪动）：
 *   - 进页面默认显示（金额是主输入）
 *   - 备注聚焦 → 瞬时隐藏（display，不走动画，消除切换闪动）
 *   - 备注失焦（点空白收起系统键盘）→ 保持隐藏，不闪回
 *   - 点金额行 → 从屏幕底部上滑重新显示（带动画）
 *   - 备注切回金额时系统键盘收起动画（约300ms）还在进行，立即显示数字键盘
 *     会跟着视口一起跳动（闪一下）→ 记录失焦时刻，等收起动画结束后再上滑
 */
const padVisible = ref(true)
const padInstant = ref(false)
let noteBlurAt = 0
let padShowTimer = 0

function hidePadInstant(): void {
  padInstant.value = true
  padVisible.value = false
}

function onNoteBlur(): void {
  noteBlurAt = Date.now()
}

function showPad(): void {
  window.clearTimeout(padShowTimer)
  const keyboardCollapsing = padInstant.value && Date.now() - noteBlurAt < 350
  // 先退出 display:none（仍停在屏幕外不可见），下一步移除位移触发上滑动画
  padInstant.value = false
  const reveal = (): void => { padVisible.value = true }
  if (keyboardCollapsing) padShowTimer = window.setTimeout(reveal, 320)
  else requestAnimationFrame(() => requestAnimationFrame(reveal))
}

onUnmounted(() => window.clearTimeout(padShowTimer))

/**
 * 系统键盘顶起可视视口时，把吸底提交栏同步抬到键盘上沿：
 * iOS/安卓上 position:fixed 相对布局视口，系统键盘弹出后栏体会被键盘盖住，
 * 监听 visualViewport 算出被遮挡高度并上移（键盘收起自动归零）
 */
const keyboardOffset = ref(0)
function syncKeyboardOffset(): void {
  const viewport = window.visualViewport
  keyboardOffset.value = viewport ? Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop) : 0
}
onMounted(() => window.visualViewport?.addEventListener('resize', syncKeyboardOffset))
onUnmounted(() => window.visualViewport?.removeEventListener('resize', syncKeyboardOffset))

const activeCategories = computed(() => {
  const rows = store.categories.filter((category) => category.type === type.value && !category.disabled)
  const activeParents = new Set(rows.filter((category) => category.parentId === null).map((category) => category.id))
  return rows.filter((category) => category.parentId === null || activeParents.has(category.parentId))
})
const selectedCategory = computed(() => store.categories.find((category) => category.id === categoryId.value))
const dateLabel = computed(() => formatRecordDateTime(bookedAt.value, dateCustomized.value))
/** 计算器键盘：金额实时 = 表达式求值；表达式（如 5+1+3-2）以小字显示在结果下方 */
const resultCents = computed<number | null>(() => evaluateAmountExpression(amountText.value))
const amountResultText = computed(() => resultCents.value !== null ? formatCents(resultCents.value, false) : '0.00')
const showProcess = computed(() => /[+-]/.test(amountText.value))

async function loadRecent(): Promise<void> {
  recentIds.value = (await store.repository.recentCategories(type.value)).map((category) => category.id)
}

function isAvailableCategory(category: Category | undefined, targetType: LedgerType): category is Category {
  if (!category || category.type !== targetType || category.parentId === null || category.disabled) return false
  const parent = store.categories.find((item) => item.id === category.parentId)
  return Boolean(parent && parent.parentId === null && !parent.disabled)
}

async function chooseDefault(): Promise<void> {
  const targetType = type.value
  const settings = await store.repository.getSettings()
  if (type.value !== targetType) return
  const remembered = store.categories.find((category) => category.id === settings.lastSelectedCategoryIds?.[targetType])
  const current = selectedCategory.value
  if (isAvailableCategory(current, targetType)) return
  categoryId.value = isAvailableCategory(remembered, targetType)
    ? remembered.id
    : activeCategories.value.find((category) => category.parentId !== null)?.id ?? ''
}

function openCategoryPicker(): void { pickerOpen.value = true }
function closeCategoryPicker(): void { pickerOpen.value = false }

function returnAfterRecordChange(): void {
  const back = window.history.state?.back
  if (typeof back === 'string' && back.startsWith('/')) router.back()
  else void router.replace('/')
}

function resetForNext(): void {
  // 保留当前类型 + 分类 + 日期（沿用最近输入），只清空金额 + 备注
  amountText.value = ''
  note.value = ''
  // 让分类恢复"上次选择"（保留体验一致）
}

onMounted(async () => {
  await store.initialize()
  if (!store.canWrite) activationOpen.value = true
  if (editingId.value) {
    const existing = await store.repository.getTransaction(editingId.value)
    if (!existing) { store.notify('没有找到这条流水', 'error'); await router.replace('/transactions'); return }
    type.value = existing.type
    amountText.value = formatCents(existing.amountCents, false)
    categoryId.value = existing.categoryId
    bookedAt.value = new Date(existing.bookedAt)
    dateCustomized.value = true
    note.value = existing.note
  } else if (copyFromId.value) {
    const source = await store.repository.getTransaction(copyFromId.value)
    if (!source) {
      store.notify('没有找到要复制的流水', 'error')
      await router.replace('/transactions')
      return
    }
    type.value = source.type
    amountText.value = formatCents(source.amountCents, false)
    categoryId.value = source.categoryId
    bookedAt.value = new Date(source.bookedAt)
    dateCustomized.value = true
    note.value = source.note
  } else await chooseDefault()
  await loadRecent()
  await nextTick()
})

watch(type, async () => { await chooseDefault(); await loadRecent() })

async function selectCategory(category: Category): Promise<void> {
  categoryId.value = category.id
  closeCategoryPicker()
  const settings = await store.repository.getSettings()
  await store.repository.putSettings({
    ...settings,
    lastSelectedCategoryIds: { ...settings.lastSelectedCategoryIds, [category.type]: category.id },
  })
}

/** 键盘快选行点分类：按 id 找到完整对象后走同一保存路径 */
async function quickSelectCategory(id: string): Promise<void> {
  const category = store.categories.find((item) => item.id === id)
  if (category) await selectCategory(category)
}

/** 键盘快选行数据：当前类型下最近使用的二级分类（最多 6 个，横向滚动） */
const quickCategories = computed(() => recentIds.value
  .map((id) => store.categories.find((item) => item.id === id))
  .filter((item): item is Category => Boolean(item && item.parentId !== null && item.type === type.value && !item.disabled))
  .slice(0, 6)
  .map((item) => ({ id: item.id, name: item.name })))

function confirmDate(value: Date): void {
  bookedAt.value = value
  dateCustomized.value = true
  datePickerOpen.value = false
}

async function commit(): Promise<void> {
  if (!store.canWrite) { activationOpen.value = true; return }
  const amountCents = resultCents.value
  if (amountCents === null || !Number.isSafeInteger(amountCents) || amountCents <= 0) { store.notify('请输入有效金额', 'error'); return }
  const category = selectedCategory.value
  if (!category || category.parentId === null) { store.notify('请选择分类', 'error'); return }
  if (Number.isNaN(bookedAt.value.getTime())) { store.notify('请选择有效日期', 'error'); return }
  saving.value = true
  try {
    const now = new Date().toISOString()
    const previous = editingId.value ? await store.repository.getTransaction(editingId.value) : undefined
    await store.repository.putTransaction({
      id: editingId.value ?? crypto.randomUUID(),
      type: type.value,
      amountCents,
      categoryId: category.id,
      bookedAt: bookedAt.value.toISOString(),
      note: note.value.trim(),
      createdAt: previous?.createdAt ?? now,
      updatedAt: now,
    })
    await store.refresh()
    store.notify(editingId.value ? '流水已更新' : '记账成功', 'success')
    returnAfterRecordChange()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '保存失败，请重试', 'error')
  } finally { saving.value = false }
}

async function onSave(): Promise<void> {
  await commit()
}

async function onAddAnother(): Promise<void> {
  if (saving.value) return
  if (!store.canWrite) { activationOpen.value = true; return }
  // 校验当前笔合法 → 保存 → 重置金额/备注 → 留在页面
  const amountCents = resultCents.value
  if (amountCents === null || !Number.isSafeInteger(amountCents) || amountCents <= 0) { store.notify('请输入有效金额', 'error'); return }
  const category = selectedCategory.value
  if (!category || category.parentId === null) { store.notify('请选择分类', 'error'); return }
  saving.value = true
  try {
    const now = new Date().toISOString()
    await store.repository.putTransaction({
      id: crypto.randomUUID(),
      type: type.value,
      amountCents,
      categoryId: category.id,
      bookedAt: bookedAt.value.toISOString(),
      note: note.value.trim(),
      createdAt: now,
      updatedAt: now,
    })
    await store.refresh()
    store.notify('已记账，可继续下一笔', 'success')
    resetForNext()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '保存失败，请重试', 'error')
  } finally { saving.value = false }
}

async function remove(): Promise<void> {
  if (!editingId.value || !store.canWrite) return
  deleting.value = true
  try {
    await store.repository.deleteTransaction(editingId.value)
    await store.refresh()
    store.notify('流水已删除', 'success')
    returnAfterRecordChange()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '删除失败，请重试', 'error')
  } finally {
    deleting.value = false
    deleteOpen.value = false
  }
}
</script>

<template>
  <main class="record-page">
    <!-- 顶部 header：返回 + 支出/收入 tab + 编辑时显示删除 -->
    <header class="record-header">
      <button type="button" class="header-button" aria-label="返回" @click="router.back()">
        <ChevronLeft :size="22" />
      </button>
      <div class="type-tabs" role="tablist" aria-label="收支类型">
        <button
          type="button"
          role="tab"
          :class="{ active: type === 'expense' }"
          :aria-selected="type === 'expense'"
          @click="type = 'expense'"
        >支出</button>
        <button
          type="button"
          role="tab"
          :class="{ active: type === 'income' }"
          :aria-selected="type === 'income'"
          @click="type = 'income'"
        >收入</button>
      </div>
      <button
        v-if="editingId"
        type="button"
        class="header-button header-danger"
        aria-label="删除"
        @click="deleteOpen = true"
      ><Trash2 :size="20" /></button>
      <span v-else class="header-spacer" />
    </header>

    <!-- 表单区：铺满页面（无卡片包裹）；金额只读展示，输入走底部自定义键盘 -->
    <form class="record-form" @submit.prevent="onSave">
      <div class="form-row amount-block" role="button" tabindex="0" aria-label="金额，点击使用数字键盘输入" @click="showPad" @keydown.enter="showPad">
        <span>金额</span>
        <div class="amount-cell">
          <span class="amount-text" :class="type">{{ amountResultText }}</span>
          <!-- 算式副层：仅在有算式时渲染，绝对定位浮在金额右下（不占位、不可点），出现/消失不挤动金额 -->
          <small v-if="showProcess" class="amount-process">{{ amountText }}</small>
        </div>
      </div>
      <button class="form-row select-row" type="button" @click="openCategoryPicker">
        <span>分类</span>
        <span class="row-value">
          <CategoryIcon v-if="selectedCategory" :name="selectedCategory.icon" :size="20" />
          {{ selectedCategory?.name ?? '请选择' }}<ChevronDown :size="19" aria-hidden="true" />
        </span>
      </button>
      <button class="form-row select-row" type="button" :aria-label="`日期 ${dateLabel}`" @click="datePickerOpen = true">
        <span>日期</span>
        <span class="row-value">{{ dateLabel }}<ChevronDown :size="19" aria-hidden="true" /></span>
      </button>
      <label class="form-row note-block">
        <span class="field-title">备注</span>
        <textarea v-model="note" maxlength="100" rows="3" placeholder="请输入" @focus="hidePadInstant" @blur="onNoteBlur" />
      </label>
    </form>
  </main>

  <!-- 底部：自定义数字键盘（固定吸底，含保存 / 再记）；点金额行上滑显示，备注输入时收起且不自动弹回 -->
  <div class="pad-dock" :class="{ hidden: !padVisible, instant: padInstant }">
    <NumberPad
      v-model="amountText"
      :type="type"
      :hide-add-another="Boolean(editingId)"
      :auto-clear="Boolean(editingId)"
      :recent-categories="quickCategories"
      :selected-category-id="categoryId"
      @save="onSave"
      @add-another="onAddAnother"
      @select-category="quickSelectCategory"
    />
  </div>

  <!-- 数字键盘收起（如聚焦备注后）时的兜底提交栏：复用同一 onAddAnother/onSave，
       新增模式两列「再记一笔/保存」，编辑模式单列「保存」；系统键盘弹出时随视口上移 -->
  <div v-if="!padVisible" class="record-submit-bar" :class="{ editing: Boolean(editingId) }" :style="keyboardOffset ? { transform: `translateY(-${keyboardOffset}px)` } : undefined">
    <button v-if="!editingId" type="button" class="button secondary" :disabled="saving" @click="onAddAnother">再记一笔</button>
    <button type="button" class="button primary" :disabled="saving" @click="onSave">保存</button>
  </div>

  <CategoryPicker :open="pickerOpen" :type="type" :categories="store.categories" :selected-id="categoryId" :recent-ids="recentIds" @close="closeCategoryPicker" @select="selectCategory" @add="router.push({ name: 'category-new', query: { type } })" />
  <DateTimePickerSheet :open="datePickerOpen" :initial="bookedAt" @close="datePickerOpen = false" @confirm="confirmDate" />

  <AppDialog :open="activationOpen" title="功能未解锁" position="center" @close="activationOpen = false">
    <ConfirmGraphic :icon="Lock" strong="激活授权码后即可记账" sub="可记账和编辑流水，浏览已有账目、备份和更新不受影响" />
    <template #actions>
      <button class="button secondary equal-action" type="button" @click="router.back()">暂不</button>
      <button class="button primary equal-action" type="button" @click="router.replace('/settings/license')">去激活</button>
    </template>
  </AppDialog>
  <AppDialog :open="deleteOpen" title="确认删除流水" position="center" @close="deleteOpen = false">
    <ConfirmGraphic :icon="Trash2" tone="danger" strong="删除后不可恢复" sub="删除后将从统计和报表中移除，如需找回请先在设置中导出备份" />
    <template #actions>
      <button class="button secondary equal-action" type="button" @click="deleteOpen = false">取消</button>
      <button class="button danger equal-action" type="button" :disabled="deleting" @click="remove">{{ deleting ? '删除中' : '确认删除' }}</button>
    </template>
  </AppDialog>
</template>

<style scoped>
