  transition: transform 0.22s ease, visibility 0.22s;
}
.pad-dock.hidden { transform: translateY(100%); visibility: hidden; }
/* 备注聚焦触发的隐藏用瞬时 display（不走滑动动画，消除与系统键盘切换的闪动） */
.pad-dock.instant { display: none; transition: none; }
.pad-dock :deep(.number-pad) { width: min(100%, 688px); margin: 0 auto; }
/* 键盘收起后的兜底提交栏：吸底 + 垫安全区；新增两列（再记一笔/保存），编辑单列（保存） */
.record-submit-bar {
  position: fixed; right: 0; bottom: 0; left: 0; z-index: 20;
  display: grid; width: min(100%, 688px); margin: 0 auto;
  grid-template-columns: 1fr 1fr; gap: 12px;
  padding: 10px 16px calc(10px + var(--safe-bottom));
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  box-shadow: 0 -6px 10px rgba(10, 18, 32, 0.08);
}
.record-submit-bar.editing { grid-template-columns: 1fr; }
.record-header {
  position: sticky; z-index: 10; top: 0;
  display: grid; grid-template-columns: 56px 1fr 56px; align-items: center;
  min-height: calc(48px + var(--safe-top));
  padding: var(--safe-top) 4px 0;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.header-button {
  display: grid; width: 48px; height: 48px; place-items: center;
  border: 0; background: transparent; color: var(--color-text); border-radius: 50%; cursor: pointer;
}
.header-danger { color: var(--color-danger, #d23f31); }
