.type-tabs { display: flex; gap: 48px; justify-self: center; align-items: stretch; min-width: 0; }
.type-tabs button {
  border: 0; background: transparent; padding: 8px 2px; min-height: 36px;
  border-bottom: 2px solid transparent; margin-bottom: -1px; /* 压住 header 的 1px 分割线 */
