  width: 100%; display: flex; align-items: center; justify-content: flex-end;
  height: 32px; line-height: 32px; /* 固定行高：金额块高度与算式有无无关 */
  color: var(--color-text); text-align: right; font-size: 22px; font-weight: 800; font-variant-numeric: tabular-nums;
