  text-align: right; word-break: break-all;
}
/* 备注块：上下排版；无输入框外观（无边框无背景），点按即可输入，占位提示「请输入」（常规字重） */
.note-block { display: flex; flex-direction: column; align-items: stretch; gap: 16px; min-height: 96px; padding: 10px 20px 14px; }
.note-block .field-title { color: var(--color-text-secondary); font-size: 15px; }
