<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Plus, Search } from '@lucide/vue'
import type { Category, LedgerType } from '@/domain/models/category'
import AppDialog from '@/components/AppDialog.vue'
import CategoryIcon from '@/components/CategoryIcon.vue'
import { colorOf, softOf } from '@/domain/services/category-color'

const props = defineProps<{
  open: boolean
  type: LedgerType
  categories: Category[]
  selectedId?: string
  recentIds?: string[]
}>()

const emit = defineEmits<{ close: []; select: [category: Category]; add: [] }>()
const query = ref('')

const active = computed(() => props.categories.filter((category) => category.type === props.type && !category.disabled))
const activeParentIds = computed(() => new Set(active.value.filter((category) => category.parentId === null).map((category) => category.id)))
const groups = computed(() => active.value
  .filter((category) => category.parentId === null)
  .map((parent) => ({
    parent,
    children: active.value.filter((child) => child.parentId === parent.id),
  }))
  .filter(({ parent, children }) => {
    const term = query.value.trim().toLocaleLowerCase()
    return !term || parent.name.toLocaleLowerCase().includes(term) || children.some((child) => child.name.toLocaleLowerCase().includes(term))
  })
  .map(({ parent, children }) => {
    const term = query.value.trim().toLocaleLowerCase()
    return { parent, children: term && !parent.name.toLocaleLowerCase().includes(term) ? children.filter((child) => child.name.toLocaleLowerCase().includes(term)) : children }
  }))

const recent = computed(() => {
  const seen = new Set<string>()
  return (props.recentIds ?? [])
    .map((id) => active.value.find((category) => category.id === id))
    .filter((category): category is Category => {
      if (!category?.parentId || !activeParentIds.value.has(category.parentId) || seen.has(category.id)) return false
      seen.add(category.id)
      return true
    })
})
const selectedInRecent = computed(() => recent.value.some((category) => category.id === props.selectedId))

watch(() => props.open, (open) => { if (open) query.value = '' })

function iconStyle(category: Category, selected: boolean): { background: string; color: string } {
  const color = colorOf(category, props.categories)
  return { background: selected ? 'white' : softOf(color), color }
}
</script>

<template>
  <AppDialog :open="open" @close="emit('close')">
    <template #header>
      <div class="picker-toolbar">
        <label class="search-field">
          <span class="sr-only">搜索分类</span>
          <Search :size="19" aria-hidden="true" />
          <input v-model="query" type="search" placeholder="搜索分类" />
        </label>
        <button class="add-button" type="button" aria-label="添加分类" @click="emit('add')"><Plus :size="19" aria-hidden="true" /><span>添加</span></button>
      </div>
    </template>

    <section v-if="recent.length && !query" class="category-section">
      <h3>最近使用</h3>
      <div class="category-grid">
        <button v-for="category in recent" :key="category.id" type="button" :class="{ selected: category.id === selectedId }" @click="emit('select', category)">
          <span class="category-icon" :style="iconStyle(category, category.id === selectedId)"><CategoryIcon :name="category.icon" /></span>
          <span>{{ category.name }}</span>
        </button>
      </div>
    </section>

    <section v-for="group in groups" :key="group.parent.id" class="category-section">
      <h3>{{ group.parent.name }}</h3>
      <div class="category-grid">
        <button v-for="category in group.children" :key="category.id" type="button" :class="{ selected: !selectedInRecent && category.id === selectedId }" @click="emit('select', category)">
          <span class="category-icon" :style="iconStyle(category, !selectedInRecent && category.id === selectedId)"><CategoryIcon :name="category.icon" /></span>
          <span>{{ category.name }}</span>
        </button>
      </div>
    </section>

    <p v-if="groups.length === 0" class="empty">没有找到相关分类</p>
  </AppDialog>
</template>

<style scoped>
.picker-toolbar { display: grid; width: 100%; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
.search-field { display: flex; min-height: 48px; align-items: center; gap: 8px; padding: 0 13px; border-radius: 13px; background: var(--color-surface-muted); color: var(--color-text-secondary); }
.search-field input { width: 100%; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--color-text); }
.add-button { display: inline-flex; min-height: 48px; align-items: center; gap: 4px; padding: 0 10px; border: 0; border-radius: 13px; background: var(--color-primary-soft); color: var(--color-primary); font-weight: 700; }
.category-section { margin-top: 22px; }
.category-section h3 { display: flex; align-items: center; gap: 7px; margin: 0 0 10px; color: var(--color-text-secondary); font-size: 14px; }
.category-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.category-grid button { display: flex; min-height: 78px; align-items: center; flex-direction: column; justify-content: center; gap: 7px; padding: 7px 3px; border: 1px solid transparent; border-radius: 13px; background: transparent; color: var(--color-text); font-size: 13px; }
.category-grid button.selected { border-color: rgb(22 119 255 / 35%); background: var(--color-primary-soft); color: var(--color-primary); font-weight: 700; }
.category-icon { display: grid; width: 38px; height: 38px; place-items: center; border-radius: 12px; }
.selected .category-icon { background: white; }
.empty { padding: 42px 0; text-align: center; color: var(--color-text-secondary); }
